"""Self-extracting transfer package for Novelty Lens Portable.
Contains application code only; no credentials or local database files.
"""
import base64
import io
import zipfile
from pathlib import Path

PAYLOAD = """"""

root = Path.cwd()
with zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))) as archive:
    archive.extractall(root)
print(f"Installed: {root / 'aramco_portable'}")
print("Run: cd aramco_portable; python -m py_compile .\\app.py; python .\\app.py")